INSERT INTO `wp_postmeta` VALUES (41,24,'_preorder_steps','a:8:{i:0;a:3:{s:5:\"title\";s:83:\"รับคำสั่งซื้อเรียบร้อย (Order Received)\";s:4:\"desc\";s:102:\"ระบบได้รับการพรีออเดอร์ของท่านแล้ว\";s:4:\"date\";s:0:\"\";}i:1;a:3:{s:5:\"title\";s:90:\"สั่งซื้อสินค้าสำเร็จ (Purchased at Origin Country)\";s:4:\"desc\";s:144:\"ทำรายการสั่งซื้อสินค้าจากต่างประเทศเรียบร้อยแล้ว\";s:4:\"date\";s:0:\"\";}i:2;a:3:{s:5:\"title\";s:101:\"ถึงคลังสินค้าต่างประเทศ (Arrived at Overseas Warehouse)\";s:4:\"desc\";s:193:\"สินค้าเดินทางถึงคลังจัดเก็บในต่างประเทศแล้ว เตรียมพร้อมส่งกลับไทย\";s:4:\"date\";s:0:\"\";}i:3;a:3:{s:5:\"title\";s:100:\"ระหว่างขนส่งระหว่างประเทศ (In Transit to Thailand)\";s:4:\"desc\";s:120:\"สินค้าอยู่ระหว่างการจัดส่งมายังประเทศไทย\";s:4:\"date\";s:0:\"\";}i:4;a:3:{s:5:\"title\";s:72:\"ผ่านพิธีการศุลกากร (Customs Cleared)\";s:4:\"desc\";s:141:\"สินค้าผ่านการตรวจและเสียภาษีนำเข้าเรียบร้อยแล้ว\";s:4:\"date\";s:0:\"\";}i:5;a:3:{s:5:\"title\";s:109:\"ถึงศูนย์กระจายสินค้าในไทย (Arrived at Local Sorting Center)\";s:4:\"desc\";s:177:\"สินค้าถึงศูนย์จัดส่งในประเทศไทยและกำลังจัดเตรียมเพื่อนำจ่าย\";s:4:\"date\";s:0:\"\";}i:6;a:3:{s:5:\"title\";s:70:\"อยู่ระหว่างนำจ่าย (Out for Delivery)\";s:4:\"desc\";s:165:\"บริษัทขนส่งในประเทศกำลังนำจ่ายสินค้าไปยังที่อยู่ของท่าน\";s:4:\"date\";s:0:\"\";}i:7;a:3:{s:5:\"title\";s:48:\"จัดส่งสำเร็จ (Delivered)\";s:4:\"desc\";s:87:\"ท่านได้รับสินค้าเรียบร้อยแล้ว\";s:4:\"date\";s:0:\"\";}}');
