INSERT INTO `wp_posts` VALUES (70,0,'2026-09-27 05:20:58','2026-09-27 05:20:58','<p>Featuring a distinctive staggered cutout design and composite carbon fiber construction, this <strong>44g </strong>lightweight mouse delivers flagship precision with a <strong>3955 Master</strong> sensor, <strong>dual 8K</strong> support, ultra-low <strong>0.174ms</strong> click latency, and an ergonomic mid-size shape for fast, effortless control.<br></p>','ATK Blazing Sky Phantom Hollow Carbon Fiber Composite Wireless Gaming Mouse','<p>Official ATK Blazing Sky Phantom Hollow Carbon Fiber Composite Wireless Gaming Mouse by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-blazing-sky-phantom-hollow-carbon-fiber-composite-wireless-gaming-mouse','','','2026-09-27 05:39:01','2026-09-27 05:39:01','',0,'http://raka-gadget.local/product/atk-blazing-sky-phantom-hollow-carbon-fiber-composite-wireless-gaming-mouse/',0,'product','',0);
