INSERT INTO `wp_posts` VALUES (79,0,'2026-09-27 05:21:08','2026-09-27 05:21:08','<p>Built for competitive play with a coating-free micro-etched tempered glass surface, smooth CNC-chamfered edges, and a secure silicone base. The spacious 490 × 420mm design delivers precise tracking, fast swipes, and consistent control for both speed-focused and control-focused gameplay.<br><br><em>Note: Due to the product’s oversized packaging and heavier weight, shipping costs may be slightly higher.<br></em><br></p>','ATK Riffle Esports Glass Mouse Pad','<p>Official ATK Riffle Esports Glass Mouse Pad by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-riffle-esports-glass-mouse-pad','','','2026-09-27 05:39:01','2026-09-27 05:39:01','',0,'http://raka-gadget.local/product/atk-riffle-esports-glass-mouse-pad/',0,'product','',0);
