INSERT INTO `wp_posts` VALUES (133,0,'2026-09-27 05:21:44','2026-09-27 05:21:44','<p style=\"font-size: 16px;line-height: 1.6;color: #222222;margin: 0\">Built with champion <span>esports</span> team <strong style=\"color: #1e6bff;font-weight: bold\">LEVIATÁN</strong>, <span>the all-new ATK F1 Series is refined and made for serious competitors.</span> A PAW3955 Master flagship sensor, Nordic 54 Series MCU, and 36g hole-free lightweight shell come together to deliver faster reactions, sharper aim, and total control under pressure.</p>','ATK Blazing Sky F1 V3 Series Esports Wireless Mouse','<p>Official ATK Blazing Sky F1 V3 Series Esports Wireless Mouse by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-blazing-sky-f1-v3-series-esports-wireless-mouse','','','2026-09-27 05:39:01','2026-09-27 05:39:01','',0,'http://raka-gadget.local/product/atk-blazing-sky-f1-v3-series-esports-wireless-mouse/',0,'product','',0);
