INSERT INTO `wp_posts` VALUES (165,0,'2026-09-27 05:21:57','2026-09-27 05:21:57','<p class=\"text-size-chat leading-[calc(var(--codex-chat-font-size)+8px)] extension:leading-normal my-2\">Refresh your Yogo 75 with the ATK Yogo 75 Exclusive Retro Low DSA PBT Keycap Set. Featuring a retro-inspired colorway and a low DSA profile, this 89-key set brings a clean, uniform look and comfortable typing feel to your low-profile keyboard setup.</p>\n<p class=\"text-size-chat leading-[calc(var(--codex-chat-font-size)+8px)] extension:leading-normal my-2\">Made from durable PBT material with dye-sublimated legends, the keycaps are built for long-lasting texture, crisp characters, and everyday use. Designed as an exclusive upgrade for Yogo 75 users, it is a perfect way to personalize your keyboard with a classic retro style.</p>','ATK Exclusive Retro Low DSA PBT Keycap Set','<p>Official ATK Exclusive Retro Low DSA PBT Keycap Set by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-exclusive-retro-low-dsa-pbt-keycap-set','','','2026-09-27 05:31:11','2026-09-27 05:31:11','',0,'http://raka-gadget.local/product/atk-exclusive-retro-low-dsa-pbt-keycap-set/',0,'product','',0);
