INSERT INTO `wp_posts` VALUES (170,0,'2026-09-27 05:22:00','2026-09-27 05:22:00','<p class=\"text-size-chat leading-[calc(var(--codex-chat-font-size)+8px)] extension:leading-normal my-2\">Designed specifically for the ATK Yogo 75 low-profile mechanical keyboard, this fitted carrying case keeps your keyboard protected and easy to carry. Its slim profile matches the Yogo 75’s low-profile design, making it ideal for storage, travel, or keeping your setup clean when not in use.</p>\n<p class=\"text-size-chat leading-[calc(var(--codex-chat-font-size)+8px)] extension:leading-normal my-2\">Built for a precise fit, the case helps protect your keyboard from everyday dust, scratches, and light bumps while maintaining a clean, minimal ATK look.</p>','ATK Yogo 75 Low-Profile Keyboard Carrying Case','<p>Official ATK Yogo 75 Low-Profile Keyboard Carrying Case by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-yogo-75-low-profile-keyboard-carrying-case','','','2026-09-27 05:39:02','2026-09-27 05:39:02','',0,'http://raka-gadget.local/product/atk-yogo-75-low-profile-keyboard-carrying-case/',0,'product','',0);
