INSERT INTO `wp_posts` VALUES (180,0,'2026-09-27 05:22:08','2026-09-27 05:22:08','<div><span class=\"text-only\">A coiled nylon design and GX12 5-<span class=\"text-only text-with-abbreviation text-with-abbreviation-bottomline\">pin</span> aviator connector bring a clean, premium finish to any keyboard setup. With a 290cm total length, USB-A to Type-C connection, and 5V 3A output, it balances flexible cable routing with reliable everyday use.</span></div>','ATK Customized 8K Aviator Coiled Keyboard Cable','<p>Official ATK Customized 8K Aviator Coiled Keyboard Cable by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-customized-8k-aviator-coiled-keyboard-cable','','','2026-09-27 05:39:02','2026-09-27 05:39:02','',0,'http://raka-gadget.local/product/atk-customized-8k-aviator-coiled-keyboard-cable/',0,'product','',0);
