INSERT INTO `wp_posts` VALUES (211,0,'2026-09-27 05:22:47','2026-09-27 05:22:47','<p>Designed to protect your gaming mouse in style, this carbon-fiber-textured case features an internal support frame for enhanced durability and stability. Weighing approximately <strong>287g</strong> and measuring <strong>89.0 x 86.5 x 186.5mm</strong>, it offers reliable protection and portability.</p>','Carbon Fiber Hard-shell Mouse Armory Case','<p>Official Carbon Fiber Hard-shell Mouse Armory Case by ATK Gear with esports grade performance.</p>','publish','open','closed','','carbon-fiber-hard-shell-mouse-armory-case','','','2026-09-27 05:31:53','2026-09-27 05:31:53','',0,'http://raka-gadget.local/product/carbon-fiber-hard-shell-mouse-armory-case/',0,'product','',0);
