INSERT INTO `wp_posts` VALUES (583,0,'2026-09-27 05:27:11','2026-09-27 05:27:11','<div>\n<strong><span class=\"text-only\">At just 38g, the compact U2 shape gives small-to-medium hands a fast, agile feel tailored for claw grip. </span></strong><span class=\"text-only\">Its ultra-lightweight build makes quick flicks and micro-adjustments feel effortless, while flagship-level tracking and dual 8000Hz polling keep every movement precise and <span class=\"text-only text-with-abbreviation text-with-abbreviation-bottomline\">responsive</span> for competitive play.</span>\n</div>','ATK Blazing Sky U2 Mini Superlight Wireless Gaming Mouse','<p>Official ATK Blazing Sky U2 Mini Superlight Wireless Gaming Mouse by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-blazing-sky-u2-mini-superlight-wireless-gaming-mouse','','','2026-09-27 05:39:03','2026-09-27 05:39:03','',0,'http://raka-gadget.local/product/atk-blazing-sky-u2-mini-superlight-wireless-gaming-mouse/',0,'product','',0);
