INSERT INTO `wp_posts` VALUES (587,0,'2026-09-27 05:27:17','2026-09-27 05:27:17','<p>Patented Spherical Structure, Stable bottoming for consistent keystrokes</p>\n<ul>\n<li>Total Travel: 3.5 ± 0.2 mm</li>\n<li>Actuation Force: 37 ± 5 gf </li>\n<li>Durability: 100 Million+ Keystrokes </li>\n<li>Initial Magnetic Flux: 90 ± 15 Gs</li>\n<li>Bottom Magnetic Flux: 480 ± 40 Gs </li>\n</ul>','ATK Crystal Blade Magnetic Switches','<p>Official ATK Crystal Blade Magnetic Switches by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-crystal-blade-magnetic-switches','','','2026-09-27 05:39:03','2026-09-27 05:39:03','',0,'http://raka-gadget.local/product/atk-crystal-blade-magnetic-switches/',0,'product','',0);
