INSERT INTO `wp_posts` VALUES (703,0,'2026-09-27 05:28:26','2026-09-27 05:28:26','<div><span class=\"text-only\">Precision comes first with Hall Effect joysticks and adjustable three-stage triggers, giving you finer control across different game genres. Micro-switch ABXY buttons add crisp response, while immersive haptics, tri-mode <span class=\"text-only text-with-abbreviation text-with-abbreviation-bottomline\">connectivity</span>, and cross-platform support make it easy to play your way across devices.</span></div>','ATK AXE Series Tri-Mode Wireless Game Controller','<p>Official ATK AXE Series Tri-Mode Wireless Game Controller by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-axe-series-tri-mode-wireless-game-controller','','','2026-09-27 05:39:04','2026-09-27 05:39:04','',0,'http://raka-gadget.local/product/atk-axe-series-tri-mode-wireless-game-controller/',0,'product','',0);
