INSERT INTO `wp_posts` VALUES (1545,0,'2026-09-27 05:38:10','2026-09-27 05:38:10','<div><span class=\"text-only\">A finely woven composite surface keeps glide smooth and controlled, with stable start-stop behavior for precise tracking and positioning. The XSoft Japanese Inoue PORON base adds cushioned support and a planted feel, finished in LEVIATAN’s signature blue co-branded design.</span></div>','ATK x LEVIATAN Esports Gaming Mouse Pad','<p>Official ATK x LEVIATAN Esports Gaming Mouse Pad by ATK Gear with esports grade performance.</p>','publish','open','closed','','atk-x-leviatan-esports-gaming-mouse-pad','','','2026-09-27 05:38:10','2026-09-27 05:38:10','',0,'http://raka-gadget.local/product/atk-x-leviatan-esports-gaming-mouse-pad/',0,'product','',0);
