INSERT INTO `wp_posts` VALUES (1627,0,'2026-09-27 05:38:59','2026-09-27 05:38:59','<p><span>Introducing the R1 Series, built for both office work and esports with greater all-around versatility. With an ultra-lightweight mouse body as low as 48g, it features a Smooth ice-feeling coating that resists stains and is easy to clean, bringing a stable and comfortable grip. Equipped with PAW3395 /PAW3395 SE flagship sensors and powered by Nordic Master MCU, it delivers high-precision tracking and ultra-low latency. Made for competitive gaming.</span></p>','VXE Dragonfly R1 Series Wireless Mouse','<p>Official VXE Dragonfly R1 Series Wireless Mouse by ATK Gear with esports grade performance.</p>','publish','open','closed','','vxe-dragonfly-r1-series-wireless-mouse','','','2026-09-27 05:45:10','2026-09-27 05:45:10','',0,'http://raka-gadget.local/product/vxe-dragonfly-r1-series-wireless-mouse/',0,'product','',0);
